def relatorio_vendas(vendas: list[dict]) -> dict:
    """Gera um resumo com total, quantidade e produto mais vendido."""
    if not vendas:
        return {
            'total_vendas': 0.0,
            'quantidade_itens': 0,
            'produto_mais_vendido': 'Nenhum',
        }

    total = 0.0
    contagem = {}

    for venda in vendas:
        valor = float(venda['valor'])
        quantidade = int(venda['quantidade'])
        total += valor * quantidade
        produto = venda['produto']
        contagem[produto] = contagem.get(produto, 0) + quantidade

    produto_mais_vendido = max(contagem, key=contagem.get)

    return {
        'total_vendas': round(total, 2),
        'quantidade_itens': sum(contagem.values()),
        'produto_mais_vendido': produto_mais_vendido,
    }
